PROGRAM ST_C03_FORMATBYTE
VAR
    steg       : INT := 1;
    tmrCam     : TON;
    tmrRakn    : TON;
    prdForra   : INT := 0;
    xRaknefel  : BOOL := FALSE;
    formatValt : INT := 1;
END_VAR

tmrCam(IN := (steg = 3), PT := T#5000ms);

(* Kartongraknaren ar scenens, inte styrningens, och den kan bara provas mot
   det styrningen sjalv vet: om bandet gar och hur fort.
   Halv takt ar 5,0 kartonger per minut, alltsa 12,0 s per kartong; tva sadana
   takter = 24,0 s ar den langsta lucka som kan vara en lucka i flodet i
   stallet for en trasig raknare (scenariot cnt_lag: raknaren star kvar pa 0 i
   300 s medan bandet gar). Och en raknare som stiger medan bandet star kan
   inte rakna kartonger (scenariot cnt_hog: 700 pa en timme mot de 520 takten
   medger). Bada ar rakningsfel, och ett kapacitetsmal mat med en trasig
   raknare ar inget mal: linan stannar och begar manuell kontroll. *)
tmrRakn(IN := ST410_CNV_RUN AND (ST410_PRD_CNT = prdForra), PT := T#24000ms);
IF tmrRakn.Q THEN
    xRaknefel := TRUE;
END_IF;
IF NOT ST410_CNV_RUN AND ST410_PRD_CNT > prdForra THEN
    xRaknefel := TRUE;
END_IF;
prdForra := ST410_PRD_CNT;

IF NOT EMG_OK THEN
    ST410_CNV_RUN  := FALSE;
    ST410_LNE_SPD  := 0.0;
    ST410_FMT_CHG  := FALSE;
    ST410_CAM_TRIG := FALSE;
    ST410_STA_STOP := FALSE;
    steg := 0;
ELSE
    IF xRaknefel THEN
        steg := 9;
    END_IF;
    CASE steg OF
        0:
            IF EMG_OK THEN
                steg := 1;
            END_IF;
        1:
            ST410_STA_STOP := FALSE;
            ST410_FMT_CHG  := FALSE;
            ST410_CAM_TRIG := FALSE;
            ST410_CNV_RUN  := TRUE;
            ST410_LNE_SPD  := 10.0;
            IF NOT ST410_FMT_RDY THEN
                steg := 2;
            END_IF;
        2:
            ST410_CNV_RUN  := FALSE;
            ST410_LNE_SPD  := 0.0;
            ST410_FMT_CHG  := TRUE;
            ST410_CAM_TRIG := FALSE;
            IF ST410_FMT_RDY THEN
                formatValt := ST410_FMT_SEL;
                IF formatValt < 1 OR formatValt > 2 THEN
                    ST410_STA_STOP := TRUE;
                    ST410_FMT_CHG  := FALSE;
                    steg := 9;
                ELSE
                    ST410_FMT_CHG  := FALSE;
                    ST410_CNV_RUN  := TRUE;
                    ST410_LNE_SPD  := 5.0;
                    ST410_CAM_TRIG := TRUE;
                    steg := 3;
                END_IF;
            END_IF;
        3:
            IF ST410_CAM_OK THEN
                ST410_CAM_TRIG := FALSE;
                ST410_LNE_SPD  := 10.0;
                steg := 1;
            ELSIF tmrCam.Q THEN
                ST410_CAM_TRIG := FALSE;
                ST410_CNV_RUN  := FALSE;
                ST410_LNE_SPD  := 0.0;
                ST410_STA_STOP := TRUE;
                steg := 9;
            END_IF;
        9:
            ST410_CNV_RUN  := FALSE;
            ST410_LNE_SPD  := 0.0;
            ST410_CAM_TRIG := FALSE;
            ST410_STA_STOP := TRUE;
    END_CASE;
END_IF;
END_PROGRAM

